// The UK demo carries its own JavaScript port of tools/gridcode/ukgrid.py. This
// runs that port against a fixture generated by the Python reference, so the two
// cannot drift. Regenerate with tools/gridcode/build_uk_fixture.py after any change.
import { readFileSync, writeFileSync, rmSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, '..', '..', 'demos', 'uk-grid.html'), 'utf8');
const fixture = JSON.parse(readFileSync(join(here, 'fixture-uk.json'), 'utf8'));

let bad = 0;
const fail = (msg) => { bad++; console.error(`  ${msg}`); };

const words = html.match(/const WORDS = (\[[^\n]*\]);/)[1];
const listed = readFileSync(
  join(here, '..', 'wordlist', 'spoken-1296-plain.txt'), 'utf8').trim().split('\n');
if (JSON.parse(words).join('\n') !== listed.join('\n'))
  fail("the demo's word list is not tools/wordlist/spoken-1296-plain.txt");
// The demo embeds the mask; the reference reads it from a file.
const mask = html.match(/const MASK = '([^']*)';/)[1];
if (mask !== readFileSync(join(here, 'uk-mask.txt'), 'utf8').trim())
  fail("the demo's mask is not tools/gridcode/uk-mask.txt");

const src = `const WORDS = ${words};\n`
  + html.slice(html.indexOf('const INDEX = new Map'), html.indexOf('// --- map ---'))
  + '\nexport { valueAt, centreOf, encode, decodeValue, scramble, unscramble, parseAddress,'
  + ' digitsAt, quarterAt, quarterOf, centreOfQuarter, parseFull, K, CELLS, SQUARES };';
const tmp = join(here, `.check-uk-demo-${process.pid}.mjs`);
writeFileSync(tmp, src);
let mod;
try { mod = await import(pathToFileURL(tmp).href); } finally { rmSync(tmp, { force: true }); }

if (mod.K !== fixture.k) fail(`K: js ${mod.K} vs py ${fixture.k}`);
if (mod.CELLS !== fixture.cells) fail(`cells: js ${mod.CELLS} vs py ${fixture.cells}`);
if (mod.SQUARES.length !== fixture.squares)
  fail(`squares: js ${mod.SQUARES.length} vs py ${fixture.squares}`);

for (const [v, n] of fixture.scramble) {
  if (mod.scramble(v) !== n) fail(`SCRAMBLE ${v}: js ${mod.scramble(v)} vs py ${n}`);
  if (mod.unscramble(n) !== v) fail(`UNSCRAMBLE ${n}: js ${mod.unscramble(n)} vs py ${v}`);
}

for (const c of fixture.points) {
  const v = mod.valueAt(c.lat, c.lng);
  if (v !== c.value) fail(`VALUE ${c.lat},${c.lng}: js ${v} vs py ${c.value}`);
  const got = mod.encode(c.lat, c.lng);
  if (got.join('.') !== c.words.join('.'))
    fail(`MISMATCH ${c.lat},${c.lng}: js ${got.join('.')} vs py ${c.words.join('.')}`);
  const [la, lo] = mod.centreOf(c.value);
  // Trigonometry may differ in the last bit between the two runtimes.
  if (Math.abs(la - c.centre[0]) > 1e-9 || Math.abs(lo - c.centre[1]) > 1e-9)
    fail(`CENTRE ${c.value}: js ${[la, lo]} vs py ${c.centre}`);
  try {
    if (mod.decodeValue(c.words) !== c.value) fail(`DECODE ${c.words.join('.')}`);
  } catch (e) { fail(`DECODE ${c.words.join('.')}: ${e.message}`); }
}

// The optional number: the digits for a point, the quarter they name, and which
// of all 100 numbers fit a cell.
for (const c of fixture.points) {
  if (mod.digitsAt(c.lat, c.lng) !== c.digits)
    fail(`DIGITS ${c.lat},${c.lng}: js ${mod.digitsAt(c.lat, c.lng)} vs py ${c.digits}`);
  if (mod.quarterAt(c.lat, c.lng) !== c.quarter) fail(`QUARTER ${c.lat},${c.lng}`);
  const [la, lo] = mod.centreOfQuarter(c.value, mod.quarterOf(c.value, c.digits));
  if (Math.abs(la - c.quarter_centre[0]) > 1e-9 || Math.abs(lo - c.quarter_centre[1]) > 1e-9)
    fail(`QUARTER CENTRE ${c.value}: js ${[la, lo]} vs py ${c.quarter_centre}`);
}
for (const n of fixture.numbers) {
  const fits = [];
  for (let d = 0; d < 100; d++) {
    try { mod.quarterOf(n.value, d); fits.push(d); } catch { /* does not fit */ }
  }
  if (fits.join(',') !== n.fits.join(','))
    fail(`NUMBERS for ${n.value}: js ${fits} vs py ${n.fits}`);
}
for (const [text, [words, num]] of fixture.parse) {
  const [w, n] = mod.parseFull(text);
  if (w.join('.') !== words.join('.') || n !== num)
    fail(`PARSE ${JSON.stringify(text)}: js ${[w, n]} vs py ${[words, num]}`);
}

for (const [la, lo] of fixture.outside)
  if (mod.valueAt(la, lo) !== null) fail(`OUTSIDE ${la},${lo} has a value in js`);

for (const w of fixture.wrong) {
  let got = null;
  try { got = mod.decodeValue(w.words); } catch { /* refused */ }
  if (got !== w.value) fail(`WRONG ${w.words.join('.')}: js ${got} vs py ${w.value}`);
}

if (mod.parseAddress('  STUDIO, scribble Critical ').length !== 3) fail('PARSE');

console.log(`uk demo codec vs python reference: ${fixture.points.length} points, `
  + `${fixture.scramble.length} scrambles, ${fixture.wrong.length} wrong words`);
if (bad) { console.error(`FAIL: ${bad} problem(s)`); process.exit(1); }
console.log('OK: the mask, the scramble, cells, encodings and wrong-word handling all match');
